"""The retailer usage export reader (P2 spec §4.3, §13.1). Every file is generated by `make_sources`."""

import dataclasses
from datetime import datetime
from decimal import Decimal
from types import MappingProxyType

import pytest

from energatron.core.errors import InvalidInputError
from energatron.core.retailer_usage import UsageRead, UsageRow, UsageScan, read_usage_export, scan_usage_export
from tests.fixtures.make_sources import make_retailer_usage_csv
from tests.fixtures.synthetic import SYNTHETIC_ACCOUNT, SYNTHETIC_SERIAL

S = SYNTHETIC_SERIAL


def usage(months: int = 3, **kw: object) -> bytes:
    return make_retailer_usage_csv(months, **kw)  # type: ignore[arg-type]


def export(*rows: str, header: str | None = None) -> bytes:
    head = header or f"Account Code,Read Datetime,E1 ({S} - Off Peak),B1 ({S} - Export),Total"
    return "".join(line + "\r\n" for line in (head, *rows)).encode()


def edit(data: bytes, old: str, new: str) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, 1).encode("utf-8")


def outcome(function: object, data: bytes) -> str:
    assert callable(function)
    try:
        function(data)
    except InvalidInputError as error:
        assert error.details["source"] == "retailer_usage"
        return f"rejected:{error.details['reason']}"
    return "accepted"


def test_read_returns_labels_suffixes_and_rows_in_file_order() -> None:
    read = read_usage_export(usage(3))
    assert read.labels == ("Off Peak", "Peak", "Shoulder")
    assert read.suffixes == ("E1",)
    assert [row.read_dt for row in read.rows] == [datetime(2025, 1, 1), datetime(2025, 2, 1), datetime(2025, 3, 1)]
    assert read.rows[0] == UsageRow(
        read_dt=datetime(2025, 1, 1),
        values={"Off Peak": Decimal("100.000"), "Peak": Decimal("101.000"), "Shoulder": Decimal("102.000")},
        total=Decimal("303.000"),
    )


def test_labels_are_sorted_and_rows_stay_in_file_order() -> None:
    data = usage(2, labels=("Shoulder", "Peak"), register="B1")
    lines = data.split(b"\r\n")
    data = b"\r\n".join([lines[0], lines[2], lines[1], b""])
    read = read_usage_export(data)
    assert read.labels == ("Peak", "Shoulder")
    assert read.suffixes == ("B1",)
    assert [row.read_dt for row in read.rows] == [datetime(2025, 2, 1), datetime(2025, 1, 1)]
    assert list(read.rows[0].values) == ["Shoulder", "Peak"]  # the label as written, in column order


def test_an_empty_cell_is_none_and_a_blank_row_has_a_none_total() -> None:
    last = read_usage_export(usage(2, blank_last=True)).rows[-1]
    assert last.total is None
    assert last.values == {"Off Peak": None, "Peak": None, "Shoulder": None}


def test_a_partly_empty_row() -> None:
    data = export(f"{SYNTHETIC_ACCOUNT},2025-01-01T00:00:00,1.5,,1.5")
    row = read_usage_export(data).rows[0]
    assert row.values == {"Off Peak": Decimal("1.5"), "Export": None}
    assert row.total == Decimal("1.5")


def test_two_registers_give_both_suffixes_and_each_label() -> None:
    read = read_usage_export(export(f"{SYNTHETIC_ACCOUNT},2025-01-01T00:00:00,1.5,0.25,1.75"))
    assert read.suffixes == ("B1", "E1")
    assert read.labels == ("Export", "Off Peak")


def test_two_registers_with_one_label_are_refused_by_read_but_not_by_scan() -> None:
    data = export(
        f"{SYNTHETIC_ACCOUNT},2025-01-01T00:00:00,1.5,0.25,1.75",
        header=f"Account Code,Read Datetime,E1 ({S} - Peak),B1 ({S} - Peak),Total",
    )
    assert outcome(scan_usage_export, data) == "accepted"
    assert outcome(read_usage_export, data) == "rejected:duplicate_label"


def test_scan_returns_the_same_rows_plus_the_identifiers() -> None:
    scan = scan_usage_export(usage(3))
    read = read_usage_export(usage(3))
    assert scan.rows == read.rows and scan.labels == read.labels and scan.suffixes == read.suffixes
    assert scan.accounts == (SYNTHETIC_ACCOUNT,)
    assert scan.serials == (SYNTHETIC_SERIAL,)


def test_the_identifiers_are_distinct_values_in_first_seen_order() -> None:
    data = edit(usage(3), f"\r\n{SYNTHETIC_ACCOUNT},2025-02-01", "\r\n900000000002,2025-02-01")
    assert scan_usage_export(data).accounts == (SYNTHETIC_ACCOUNT, "900000000002")


def test_read_result_types_have_no_identifier_field() -> None:
    for model in (UsageRead, UsageRow):
        names = {field.name for field in dataclasses.fields(model)}
        assert not {name for name in names if any(word in name for word in ("nmi", "serial", "account", "ident"))}
    assert {field.name for field in dataclasses.fields(UsageRead)} == {"labels", "suffixes", "rows"}
    assert {field.name for field in dataclasses.fields(UsageScan)} == {
        "labels",
        "suffixes",
        "rows",
        "accounts",
        "serials",
    }


def test_the_bom_and_lf_are_accepted() -> None:
    expected = read_usage_export(usage()).rows
    assert read_usage_export(b"\xef\xbb\xbf" + usage().replace(b"\r\n", b"\n")).rows == expected


CASES: dict[str, tuple[bytes, str]] = {
    "valid": (usage(), "accepted"),
    "blank_last": (usage(blank_last=True), "accepted"),
    "extra_field": (edit(usage(), ",2025-02-01T00:00:00,", ",2025-02-01T00:00:00,1,"), "rejected:bad_field_count"),
    "date_only": (edit(usage(), ",2025-02-01T00:00:00,", ",2025-02-01,"), "rejected:bad_datetime"),
    "february_30": (edit(usage(), ",2025-02-01T00:00:00,", ",2025-02-30T00:00:00,"), "rejected:bad_datetime"),
    "text_number": (edit(usage(), ",110.000,", ",n/a,"), "rejected:bad_number"),
    "bad_header": (edit(usage(), "Account Code,", "Account,"), "rejected:bad_header"),
    "header_only": (usage(0), "rejected:no_data"),
    "not_utf8": (usage() + b"\xff\r\n", "rejected:not_utf8"),
}


@pytest.mark.parametrize("name", list(CASES))
def test_scan_and_read_accept_and_reject_exactly_the_same_files(name: str) -> None:
    data, expected = CASES[name]
    assert outcome(scan_usage_export, data) == expected
    assert outcome(read_usage_export, data) == expected


def test_an_error_never_holds_an_identifier_or_content() -> None:
    with pytest.raises(InvalidInputError) as caught:
        read_usage_export(edit(usage(), ",110.000,", ",n/a,"))
    text = caught.value.message + repr(caught.value.details)
    assert SYNTHETIC_ACCOUNT not in text and SYNTHETIC_SERIAL not in text and "n/a" not in text


def test_a_rows_values_cannot_be_mutated() -> None:
    row = read_usage_export(usage()).rows[0]
    assert isinstance(row.values, MappingProxyType)
    with pytest.raises(TypeError):
        row.values["Peak"] = Decimal(0)  # type: ignore[index]
    with pytest.raises(dataclasses.FrozenInstanceError):
        row.total = None  # type: ignore[misc]
    assert scan_usage_export(usage()).rows[0].values == row.values


def test_a_row_still_equals_one_built_from_a_dict() -> None:
    row = read_usage_export(usage()).rows[0]
    rebuilt = UsageRow(read_dt=row.read_dt, values=dict(row.values), total=row.total)
    assert rebuilt == row
